import React, { useState, useRef } from "react";
import { motion } from "framer-motion";
import { ArrowLeft, ArrowRight } from "lucide-react";

const SLIDERS = [
  {
    id: 1,
    title: "Round Table Transformation",
    before: "https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&auto=format",
    after: "https://images.unsplash.com/photo-1734705797834-a356d77e4140?w=800&auto=format",
    beforeLabel: "Before",
    afterLabel: "After",
    desc: "Ordinary table → Elegant centerpiece"
  },
  {
    id: 2,
    title: "Chair Elegance",
    before: "https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&auto=format",
    after: "https://images.unsplash.com/photo-1528221297180-b340bcc21812?w=800&auto=format",
    beforeLabel: "Plain Chairs",
    afterLabel: "Dressed Chairs",
    desc: "Simple seating → Royal elegance"
  },
  {
    id: 3,
    title: "Ceiling Magic",
    before: "https://images.unsplash.com/photo-1530103862676-de8c9de4abcb?w=800&auto=format",
    after: "https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=800&auto=format",
    beforeLabel: "Bare Ceiling",
    afterLabel: "Drape Magic",
    desc: "Basic venue → Magical atmosphere"
  },
  {
    id: 4,
    title: "Entrance Transformation",
    desc: "Entrance transformed with drapes & florals",
    before: "https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?w=800&auto=format",
    after: "https://images.unsplash.com/photo-1519225421980-715cb0215aed?w=800&auto=format",
    beforeLabel: "Standard Entrance",
    afterLabel: "Grand Entrance",
    desc: "Simple entry → Memorable welcome"
  }
];

export default function BeforeAfter() {
  const [activeSlide, setActiveSlide] = useState(0);
  const [position, setPosition] = useState(50);
  const [isDragging, setIsDragging] = useState(false);
  const sliderRef = useRef(null);

  const current = SLIDERS[activeSlide];

  const handleMouseMove = (e) => {
    if (!sliderRef.current || !isDragging) return;
    const rect = sliderRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(100, (e.clientX - rect.left) / rect.width * 100));
    setPosition(x);
  };

  const handleTouchMove = (e) => {
    if (!sliderRef.current || !isDragging) return;
    const touch = e.touches[0];
    const rect = sliderRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(100, (touch.clientX - rect.left) / rect.width * 100));
    setPosition(x);
  };

  return (
    <section id="transformation" className="py-20 md:py-28" style={{ background: "linear-gradient(180deg, #fff9ed 0%, #ffffff 100%)" }}>
      <div className="px-6 md:px-12 lg:px-24">

        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="text-center mb-12"
        >
          <p className="text-xs tracking-[0.3em] uppercase mb-3 font-semibold" style={{ color: "#d4af37" }}>Transformation</p>
          <h2 style={{ fontSize: "clamp(36px, 4vw, 56px)", lineHeight: 1.1, fontWeight: 700, color: "#1a080a", fontFamily: "Outfit, sans-serif" }}>
            See the <span style={{ color: "#d4af37", fontWeight: 700 }}>Magic</span> We Create
          </h2>
          <p className="text-lg mt-4 max-w-xl mx-auto font-medium" style={{ color: "rgba(26,8,10,0.75)" }}>
            Drag the slider to see the transformation from ordinary to extraordinary
          </p>
        </motion.div>

        {/* Slider Navigation */}
        <div className="flex justify-center gap-3 mb-8">
          {SLIDERS.map((slide, i) => (
            <button
              key={slide.id}
              onClick={() => { setActiveSlide(i); setPosition(50); }}
              className="px-4 py-2 rounded-full text-sm transition-all"
              style={{
                background: activeSlide === i ? "linear-gradient(135deg, #d4af37, #f4d77a)" : "transparent",
                color: activeSlide === i ? "#1a080a" : "rgba(26,8,10,0.6)",
                border: activeSlide === i ? "none" : "1px solid rgba(212,175,55,0.3)",
                fontWeight: activeSlide === i ? 600 : 400
              }}
            >
              {i + 1}
            </button>
          ))}
        </div>

        {/* Before/After Slider */}
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="max-w-4xl mx-auto"
        >
          <div
            ref={sliderRef}
            className="relative rounded-2xl overflow-hidden cursor-ew-resize select-none"
            style={{ aspectRatio: "16/10" }}
            onMouseDown={() => setIsDragging(true)}
            onMouseUp={() => setIsDragging(false)}
            onMouseLeave={() => setIsDragging(false)}
            onMouseMove={handleMouseMove}
            onTouchStart={() => setIsDragging(true)}
            onTouchEnd={() => setIsDragging(false)}
            onTouchMove={handleTouchMove}
          >
            {/* After Image (Background) */}
            <div className="absolute inset-0">
              <img
                src={current.after}
                alt="After"
                className="w-full h-full object-cover"
                draggable={false}
              />
              <div className="absolute bottom-4 right-4 px-4 py-2 rounded-full text-sm font-semibold"
                style={{
                  background: "rgba(0,0,0,0.7)",
                  color: "white"
                }}
              >
                {current.afterLabel}
              </div>
            </div>

            {/* Before Image (Clipped) */}
            <div
              className="absolute inset-0 overflow-hidden"
              style={{ width: `${position}%` }}
            >
              <img
                src={current.before}
                alt="Before"
                className="absolute inset-0 min-w-full min-h-full object-cover"
                draggable={false}
                style={{ width: `${10000 / position}%`, maxWidth: "none" }}
              />
              <div className="absolute bottom-4 left-4 px-4 py-2 rounded-full text-sm font-semibold"
                style={{ background: "rgba(0,0,0,0.7)", color: "white" }}
              >
                {current.beforeLabel}
              </div>
            </div>

            {/* Slider Handle */}
            <div
              className="absolute top-0 bottom-0 w-1 cursor-ew-resize"
              style={{
                left: `${position}%`,
                transform: "translateX(-50%)",
                background: "linear-gradient(180deg, #d4af37, #f4d77a, #d4af37)",
                boxShadow: "0 0 20px rgba(212,175,55,0.5)"
              }}
            >
              {/* Handle Circle */}
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 rounded-full flex items-center justify-center"
                style={{ background: "linear-gradient(135deg, #d4af37, #f4d77a)" }}
              >
                <div className="flex items-center gap-1">
                  <ArrowLeft size={14} color="#1a080a" />
                  <ArrowRight size={14} color="#1a080a" />
                </div>
              </div>
            </div>

            {/* Drag Hint */}
            {position === 50 && !isDragging && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="absolute top-4 left-1/2 -translate-x-1/2 px-4 py-2 rounded-full text-sm"
                style={{ background: "rgba(0,0,0,0.7)", color: "white" }}
              >
                ← Drag to compare →
              </motion.div>
            )}
          </div>

          {/* Title & Description */}
          <div className="text-center mt-6">
            <h3 className="text-xl font-semibold" style={{ color: "#1a080a" }}>
              {current.title}
            </h3>
            <p className="text-sm mt-2" style={{ color: "rgba(26,8,10,0.6)" }}>
              {current.desc}
            </p>
          </div>
        </motion.div>

        {/* Navigation Arrows */}
        <div className="flex justify-center gap-4 mt-8">
          <button
            onClick={() => { setActiveSlide(prev => prev > 0 ? prev - 1 : SLIDERS.length - 1); setPosition(50); }}
            className="p-3 rounded-full transition-all hover:scale-110"
            style={{ background: "rgba(212,175,55,0.1)", border: "1px solid rgba(212,175,55,0.3)" }}
          >
            <ArrowLeft size={20} color="#d4af37" />
          </button>
          <button
            onClick={() => { setActiveSlide(prev => prev < SLIDERS.length - 1 ? prev + 1 : 0); setPosition(50); }}
