          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="text-center mt-12"
        >
          <button
            onClick={() => window.open("https://wa.me/919888919983?text=Hi!%20I'd%20like%20to%20transform%20my%20venue%20with%20D%20SAJAWAT%20fabrics", "_blank")}
